"""More knowledge: everyday pregnancy questions, tests and vaccines, common conditions, birth preparedness,
labour, postnatal care, breastfeeding, newborn care, lifestyle and food myths.

Follows MoHFW guidance (MCP card, ANC operational guidelines, HBNC, JSSK, PMMVY, Anaemia Mukt Bharat) and
WHO recommendations. Short, plain-language documents in English and Hindi so retrieval stays precise.
Clinical teams should review and adapt to their state's programme before real-world use.
"""
from __future__ import annotations

MORE_CATEGORIES = ["common_discomforts", "lifestyle", "tests_vaccines", "conditions", "birth_preparedness",
                   "labour", "postnatal", "breastfeeding", "newborn"]


def _d(id_: str, category: str, title: str, text: str, title_hi: str, text_hi: str,
       source: str = "MoHFW / WHO guidance") -> dict:
    return {"id": id_, "category": category, "title": title, "title_hi": title_hi, "text": text, "text_hi": text_hi,
            "week_from": None, "week_to": None, "source": source}


